import React, { useEffect, useState, useContext } from "react";
import { AuthContext } from "../context/AuthContext";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import { LogOut, Users, UserCheck, UserPlus, FileText, Activity } from "lucide-react";

// Protected Route Wrapper
export function ProtectedRoute({ children }) {
  const { token } = useContext(AuthContext);
  return token ? children : <Navigate to="/login" />;
}

export default function AdminDashboard() {
  const { user, token, logout } = useContext(AuthContext);
  const navigate = useNavigate();

  const [votingOpen, setVotingOpen] = useState(false);
  const [pendingUsers, setPendingUsers] = useState([]);
  const [candidates, setCandidates] = useState([]);
  const [logs, setLogs] = useState([]);

  const api = axios.create({
    baseURL: "http://localhost:4000/api/admin",
    headers: { Authorization: `Bearer ${token}` },
  });

  // ----------------------
  // Fetch initial data
  // ----------------------
  useEffect(() => {
    fetchVotingState();
    fetchPendingUsers();
    fetchCandidates();
    fetchLogs();
  }, []);

  // ----------------------
  // Graceful fetch functions
  // ----------------------
  const fetchVotingState = async () => {
    try {
      const res = await api.get("/toggle-voting"); // GET endpoint must exist in backend
      setVotingOpen(res.data.votingOpen);
    } catch (err) {
      console.warn("Voting state not found or backend down");
      setVotingOpen(false);
    }
  };

  const fetchPendingUsers = async () => {
    try { setPendingUsers((await api.get("/pending-users")).data); } catch { setPendingUsers([]); }
  };
  const fetchCandidates = async () => {
    try { setCandidates((await api.get("/candidates")).data); } catch { setCandidates([]); }
  };
  const fetchLogs = async () => {
    try { setLogs((await api.get("/logs")).data); } catch { setLogs([]); }
  };

  // ----------------------
  // Logout
  // ----------------------
  const handleLogout = () => {
    logout();          // clear token & user
    navigate("/login"); // redirect
  };

  // ----------------------
  // Voting toggle
  // ----------------------
  const toggleVoting = async () => {
    try {
      const res = await api.post("/toggle-voting");
      setVotingOpen(res.data.votingOpen);
      fetchLogs();
    } catch {
      alert("Failed to toggle voting");
    }
  };

  // ----------------------
  // Approve user
  // ----------------------
  const approveUser = async (id) => {
    try {
      await api.post(`/approve-user/${id}`);
      fetchPendingUsers();
      fetchLogs();
    } catch {
      alert("Failed to approve user");
    }
  };

  // ----------------------
  // Candidates CRUD
  // ----------------------
  const addCandidate = async () => {
    const name = prompt("Candidate name:");
    const position = prompt("Position:");
    const party = prompt("Party (optional):");
    if (!name || !position) return;
    try { await api.post("/candidates", { name, position, party }); fetchCandidates(); fetchLogs(); } catch { alert("Failed to add candidate"); }
  };
  const editCandidate = async (c) => {
    const name = prompt("New name:", c.name);
    const position = prompt("New position:", c.position);
    const party = prompt("New party:", c.party);
    try { await api.put(`/candidates/${c.id}`, { name, position, party }); fetchCandidates(); fetchLogs(); } catch { alert("Failed to edit candidate"); }
  };
  const deleteCandidate = async (id) => {
    if (!window.confirm("Are you sure?")) return;
    try { await api.delete(`/candidates/${id}`); fetchCandidates(); fetchLogs(); } catch { alert("Failed to delete candidate"); }
  };

  const generateReport = async () => { try { await api.post("/generate-report"); fetchLogs(); } catch { alert("Failed to generate report"); } };

  // ----------------------
  // Render
  // ----------------------
  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <header className="flex justify-between items-center mb-8">
        <h1 className="text-3xl font-bold text-gray-800">iVote Admin Dashboard</h1>
        <button onClick={handleLogout} className="flex items-center bg-red-600 text-white px-4 py-2 rounded shadow hover:bg-red-700">
          <LogOut className="w-5 h-5 mr-2" /> Logout
        </button>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 mb-8">
        {/* Voting */}
        <div className="bg-white p-6 rounded-2xl shadow hover:shadow-lg transition">
          <h2 className="flex items-center text-xl font-semibold mb-2"><Activity className="w-5 h-5 mr-2" /> Voting Status</h2>
          <p className="mb-4 font-medium">{votingOpen ? "Open" : "Closed"}</p>
          <button onClick={toggleVoting} className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700">
            {votingOpen ? "Close Voting" : "Open Voting"}
          </button>
        </div>

        {/* Pending Users */}
        <div className="bg-white p-6 rounded-2xl shadow hover:shadow-lg transition">
          <h2 className="flex items-center text-xl font-semibold mb-2"><UserPlus className="w-5 h-5 mr-2" /> Pending Users</h2>
          {pendingUsers.length === 0 ? <p>No pending users</p> :
            <ul className="space-y-1 max-h-40 overflow-y-auto">
              {pendingUsers.map(u => (
                <li key={u.id} className="flex justify-between items-center">
                  <span>{u.name} ({u.studentNumber})</span>
                  <button onClick={() => approveUser(u.id)} className="bg-green-600 text-white px-2 py-1 rounded hover:bg-green-700"><UserCheck className="w-4 h-4" /></button>
                </li>
              ))}
            </ul>}
        </div>

        {/* Candidates */}
        <div className="bg-white p-6 rounded-2xl shadow hover:shadow-lg transition">
          <h2 className="flex items-center text-xl font-semibold mb-2"><Users className="w-5 h-5 mr-2" /> Candidates</h2>
          <ul className="space-y-1 max-h-40 overflow-y-auto">
            {candidates.map(c => (
              <li key={c.id} className="flex justify-between items-center">
                <span>{c.name} ({c.position})</span>
                <div className="space-x-2">
                  <button onClick={() => editCandidate(c)} className="bg-yellow-500 text-white px-2 py-1 rounded hover:bg-yellow-600">Edit</button>
                  <button onClick={() => deleteCandidate(c.id)} className="bg-red-600 text-white px-2 py-1 rounded hover:bg-red-700">Delete</button>
                </div>
              </li>
            ))}
          </ul>
          <button onClick={addCandidate} className="mt-2 bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700 flex items-center"><UserPlus className="w-4 h-4 mr-2" /> Add Candidate</button>
        </div>

        {/* Logs */}
        <div className="bg-white p-6 rounded-2xl shadow hover:shadow-lg transition col-span-full">
          <h2 className="flex items-center text-xl font-semibold mb-2"><FileText className="w-5 h-5 mr-2" /> System Logs</h2>
          <ul className="max-h-48 overflow-y-auto border rounded p-2 space-y-1">
            {logs.map(log => (
              <li key={log.id}>{new Date(log.createdAt).toLocaleString()} - {log.action}</li>
            ))}
          </ul>
        </div>

        {/* Reports */}
        <div className="bg-white p-6 rounded-2xl shadow hover:shadow-lg transition col-span-full">
          <h2 className="flex items-center text-xl font-semibold mb-2"><FileText className="w-5 h-5 mr-2" /> Reports</h2>
          <button onClick={generateReport} className="bg-purple-600 text-white px-4 py-2 rounded hover:bg-purple-700 flex items-center"><FileText className="w-4 h-4 mr-2" /> Generate Report</button>
        </div>
      </div>
    </div>
  );
}
